WITH FilteredStoreSales AS (SELECT *, DATE_FORMAT(sale_date, 'yyyy-MM-dd') AS sale_date_label FROM store_sales WHERE sale_date BETWEEN '2024-03-01' AND '2024-08-01'), sale_month_summary AS (SELECT DATE_TRUNC('MONTH', sale_date) AS sale_month, AVG(units) AS avg_units FROM FilteredStoreSales GROUP BY DATE_TRUNC('MONTH', sale_date)) SELECT sale_month, avg_units FROM sale_month_summary;
